        ui.notify("连接成功：API 版本 " + (info.apiVersion || "未报告") + (info.pluginVersion ? " · 插件 " + info.pluginVersion : "") + (info.character ? " · 主角 " + info.character : "") + " · 人物 " + info.npcs + " · 物品 " + info.items + " · 生活细节 " + info.life + "。");
        return;
