        ui.notify(out.ok ? "已拉取：历史 " + out.history.length + " 字 · 人物 " + out.npcs.length + " · 物品 " + out.items.length + " · 生活细节 " + out.life.length + "。" : "没有取到资料：" + out.note);
        return;
